1	package com.example.starter.transition.service;
2	
3	import com.example.starter.transition.ApiException;
4	import com.example.starter.transition.QualityThresholds;
5	import com.example.starter.transition.TransitionStatus;
6	import com.example.starter.transition.dto.AdjustBlendRatioRequest;
7	import com.example.starter.transition.dto.ApplyOrderRequest;
8	import com.example.starter.transition.dto.BlendReadingRequest;
9	import com.example.starter.transition.dto.BlendReadingView;
10	import com.example.starter.transition.dto.BlendRecomputeView;
11	import com.example.starter.transition.dto.BlendVersionView;
12	import com.example.starter.transition.dto.DisposeRollsRequest;
13	import com.example.starter.transition.dto.ExecuteOrderRequest;
14	import com.example.starter.transition.dto.IdempotentResult;
15	import com.example.starter.transition.dto.InspectionRequest;
16	import com.example.starter.transition.dto.OrderView;
17	import com.example.starter.transition.dto.ReexamRequest;
18	import com.example.starter.transition.dto.ResumeExecutionRequest;
19	import com.example.starter.transition.dto.RollView;
20	import com.example.starter.transition.dto.TransitionRecomputeView;
21	import com.example.starter.transition.model.BlendRatioVersion;
22	import com.example.starter.transition.model.BlendReading;
23	import com.example.starter.transition.model.Grade;
24	import com.example.starter.transition.model.IdempotentRequest;
25	import com.example.starter.transition.model.RollInspection;
26	import com.example.starter.transition.model.TransitionOrder;
27	import com.example.starter.transition.model.TransitionRoll;
28	import com.example.starter.transition.repo.BlendControlEventRepository;
29	import com.example.starter.transition.repo.BlendRatioVersionRepository;
30	import com.example.starter.transition.repo.BlendReadingRepository;
31	import com.example.starter.transition.repo.CleaningWindowRepository;
32	import com.example.starter.transition.repo.GradeRepository;
33	import com.example.starter.transition.repo.IdempotentRequestRepository;
34	import com.example.starter.transition.repo.LateEventRepository;
35	import com.example.starter.transition.repo.MachineSlotRepository;
36	import com.example.starter.transition.repo.RollInspectionRepository;
37	import com.example.starter.transition.repo.TransitionOrderRepository;
38	import com.example.starter.transition.repo.TransitionRollRepository;
39	import com.example.starter.transition.repo.VerdictEventRepository;
40	import com.example.starter.transition.support.FingerprintUtil;
41	import com.fasterxml.jackson.core.type.TypeReference;
42	import com.fasterxml.jackson.databind.ObjectMapper;
43	import org.springframework.dao.DuplicateKeyException;
44	import org.springframework.stereotype.Service;
45	import org.springframework.transaction.annotation.Transactional;
46	
47	import java.math.BigDecimal;
48	import java.nio.charset.StandardCharsets;
49	import java.security.SecureRandom;
50	import java.time.Clock;
51	import java.time.LocalDateTime;
52	import java.time.format.DateTimeFormatter;
53	import java.util.HexFormat;
54	import java.util.List;
55	import java.util.Optional;
56	
57	/**
58	 * 造纸机改品种过渡料控制服务。
59	 *
60	 * <p>流转：申请→方式判定→执行→过渡料处置→完成→归档（终态）。</p>
61	 */
62	@Service
63	public class TransitionService {
64	
65	    static final String BIZ_APPLY = "APPLY_ORDER";
66	    static final String BIZ_INSPECTION = "SUBMIT_INSPECTION";
67	    static final String BIZ_REEXAM = "SUBMIT_REEXAM";
68	    static final String BIZ_ADJUST_BLEND = "ADJUST_BLEND_RATIO";
69	    static final String BIZ_BLEND_READING = "SUBMIT_BLEND_READING";
70	    static final String BIZ_RESUME = "RESUME_EXECUTION";
71	
72	    static final String INSPECTION_INITIAL = "INITIAL";
73	    static final String INSPECTION_REEXAM = "REEXAM";
74	
75	    static final String BLEND_SOURCE_APPLY = "APPLY";
76	    static final String BLEND_SOURCE_ADJUST = "ADJUST";
77	    static final String EVENT_OUT_OF_CONTROL_PAUSE = "OUT_OF_CONTROL_PAUSE";
78	    static final String EVENT_MANUAL_RESUME = "MANUAL_RESUME";
79	
80	    private static final DateTimeFormatter NO_FORMAT = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
81	    private static final SecureRandom RANDOM = new SecureRandom();
82	
83	    private final GradeRepository gradeRepository;
84	    private final TransitionOrderRepository orderRepository;
85	    private final MachineSlotRepository machineSlotRepository;
86	    private final CleaningWindowRepository cleaningWindowRepository;
87	    private final TransitionRollRepository rollRepository;
88	    private final RollInspectionRepository inspectionRepository;
89	    private final VerdictEventRepository verdictEventRepository;
90	    private final IdempotentRequestRepository idempotentRequestRepository;
91	    private final LateEventRepository lateEventRepository;
92	    private final BlendRatioVersionRepository blendRatioVersionRepository;
93	    private final BlendReadingRepository blendReadingRepository;
94	    private final BlendControlEventRepository blendControlEventRepository;
95	    private final ObjectMapper objectMapper;
96	    private final Clock clock;
97	
98	    public TransitionService(GradeRepository gradeRepository,
99	                             TransitionOrderRepository orderRepository,
100	                             MachineSlotRepository machineSlotRepository,
101	                             CleaningWindowRepository cleaningWindowRepository,
102	                             TransitionRollRepository rollRepository,
103	                             RollInspectionRepository inspectionRepository,
104	                             VerdictEventRepository verdictEventRepository,
105	                             IdempotentRequestRepository idempotentRequestRepository,
106	                             LateEventRepository lateEventRepository,
107	                             BlendRatioVersionRepository blendRatioVersionRepository,
108	                             BlendReadingRepository blendReadingRepository,
109	                             BlendControlEventRepository blendControlEventRepository,
110	                             ObjectMapper objectMapper,
111	                             Clock clock) {
112	        this.gradeRepository = gradeRepository;
113	        this.orderRepository = orderRepository;
114	        this.machineSlotRepository = machineSlotRepository;
115	        this.cleaningWindowRepository = cleaningWindowRepository;
116	        this.rollRepository = rollRepository;
117	        this.inspectionRepository = inspectionRepository;
118	        this.verdictEventRepository = verdictEventRepository;
119	        this.idempotentRequestRepository = idempotentRequestRepository;
120	        this.lateEventRepository = lateEventRepository;
121	        this.blendRatioVersionRepository = blendRatioVersionRepository;
122	        this.blendReadingRepository = blendReadingRepository;
123	        this.blendControlEventRepository = blendControlEventRepository;
124	        this.objectMapper = objectMapper;
125	        this.clock = clock;
126	    }
127	
128	    /** 申请改品种单（requestId 幂等；同一纸机同时刻唯一受理）。携带掺配比例时须重新走方式判定，判定结论与比例版本在同一事务内落库。 */
129	    @Transactional
130	    public IdempotentResult<OrderView> apply(ApplyOrderRequest request) {
131	        String fingerprint = FingerprintUtil.sha256(request.requestId(), request);
132	        IdempotentRequest existing = lookupIdempotent(request.requestId(), BIZ_APPLY, fingerprint);
133	        if (existing != null) {
134	            return replay(existing, new TypeReference<OrderView>() {
135	            });
136	        }
137	
138	        // 掺配比例须在合成允许区间内，恰在区间边界合法；先校验再占用资源。
139	        if (request.targetBlendRatioPct() != null
140	                && !TransitionRules.withinBlendInterval(request.targetBlendRatioPct())) {
141	            throw ApiException.badRequest("掺配比例 " + request.targetBlendRatioPct()
142	                    + " 超出合成允许区间 [" + QualityThresholds.BLEND_RATIO_MIN_PCT
143	                    + ", " + QualityThresholds.BLEND_RATIO_MAX_PCT + "] %");
144	        }
145	
146	        Grade fromGrade = gradeRepository.findByCode(request.fromGrade())
147	                .orElseThrow(() -> ApiException.badRequest("原品种不存在: " + request.fromGrade()));
148	        Grade toGrade = gradeRepository.findByCode(request.toGrade())
149	                .orElseThrow(() -> ApiException.badRequest("新品种不存在: " + request.toGrade()));
150	
151	        // 纸机占用：唯一索引保证同一纸机同时刻唯一受理；失败随事务回滚，不留幂等占位。
152	        String orderNo = newOrderNo();
153	        if (!machineSlotRepository.tryOccupy(request.paperMachine(), orderNo)) {
154	            throw ApiException.conflict("纸机 " + request.paperMachine() + " 已有执行中改品种单");
155	        }
156	
157	        TransitionOrder order = new TransitionOrder();
158	        order.setOrderNo(orderNo);
159	        order.setPaperMachine(request.paperMachine());
160	        order.setFromGrade(fromGrade.getGradeCode());
161	        order.setToGrade(toGrade.getGradeCode());
162	        order.setBasisWeightFrom(fromGrade.getBasisWeight());
163	        order.setBasisWeightTo(toGrade.getBasisWeight());
164	        order.setAshLevelFrom(fromGrade.getAshLevel());
165	        order.setAshLevelTo(toGrade.getAshLevel());
166	        order.setStatus(TransitionStatus.APPLIED);
167	        order.setAppliedRequestId(request.requestId());
168	        order.setAppliedAt(now());
169	        orderRepository.insert(order);
170	
171	        // 携带比例变更的申请：重新走方式判定，判定结论与比例版本在同一事务内落库。
172	        if (request.targetBlendRatioPct() != null) {
173	            applyDecision(order);
174	            BlendRatioVersion version = new BlendRatioVersion();
175	            version.setOrderNo(orderNo);
176	            version.setVersionNo(1);
177	            version.setTargetRatioPct(request.targetBlendRatioPct());
178	            version.setSource(BLEND_SOURCE_APPLY);
179	            version.setRequestId(request.requestId());
180	            version.setCreatedAt(now());
181	            blendRatioVersionRepository.tryInsert(version);
182	            orderRepository.updateBlendVersion(orderNo, 1);
183	            order.setCurrentBlendVersion(1);
184	        }
185	
186	        registerIdempotent(request.requestId(), BIZ_APPLY, fingerprint, orderNo, toView(order));
187	        return new IdempotentResult<>(request.requestId(), false, toView(order));
188	    }
189	
190	    /** 方式判定：克重差 ≤10%（含）直切；灰分等级差 &gt;2 级须冲洗网部，恰 2 级合法直切。 */
191	    @Transactional
192	    public OrderView decide(String orderNo) {
193	        TransitionOrder order = requireOrder(orderNo);
194	        requireStatus(order, TransitionStatus.APPLIED);
195	        applyDecision(order);
196	        return toView(order);
197	    }
198	
199	    /** 判定结论计算与落库：申请携带比例时与比例版本同事务调用，独立判定走 decide。 */
200	    private void applyDecision(TransitionOrder order) {
201	        BigDecimal from = order.getBasisWeightFrom();
202	        BigDecimal delta = TransitionRules.basisWeightDeltaPct(from, order.getBasisWeightTo());
203	        int ashDelta = TransitionRules.ashLevelDelta(order.getAshLevelFrom(), order.getAshLevelTo());
204	
205	        order.setBasisWeightDeltaPct(delta);
206	        order.setAshLevelDelta(ashDelta);
207	        // 恰 10.0000% 视为直切。
208	        order.setDirectSwitch(TransitionRules.isDirectSwitch(delta));
209	        // 恰 2 级合法直切；超过 2 级才冲洗网部。
210	        order.setWireFlush(TransitionRules.needsWireFlush(ashDelta));
211	        order.setStatus(TransitionStatus.DECIDED);
212	        order.setDecidedAt(now());
213	        orderRepository.updateDecision(order);
214	    }
215	
216	    /** 执行：参数须在新品种工艺窗口内（含边界）；过渡料长度 = 车速×切换时间/60。 */
217	    @Transactional
218	    public OrderView execute(String orderNo, ExecuteOrderRequest request) {
219	        TransitionOrder order = requireOrder(orderNo);
220	        requireStatus(order, TransitionStatus.DECIDED);
221	        if (request.switchTimeSec() <= 0) {
222	            throw ApiException.badRequest("切换时间须为正整数秒");
223	        }
224	        Grade toGrade = gradeRepository.findByCode(order.getToGrade())
225	                .orElseThrow(() -> ApiException.badRequest("新品种不存在: " + order.getToGrade()));
226	
227	        BigDecimal speed = request.machineSpeedMMin();
228	        BigDecimal consistency = request.stockConsistencyPct();
229	        // 恰在窗口边界视为合格。
230	        if (!TransitionRules.withinWindow(speed, toGrade.getSpeedMin(), toGrade.getSpeedMax())) {
231	            throw ApiException.badRequest("执行车速 " + speed + " 超出新品种工艺窗口 ["
232	                    + toGrade.getSpeedMin() + ", " + toGrade.getSpeedMax() + "] m/min");
233	        }
234	        if (!TransitionRules.withinWindow(consistency, toGrade.getConsistencyMin(),
235	                toGrade.getConsistencyMax())) {
236	            throw ApiException.badRequest("上料浓度 " + consistency + " 超出新品种工艺窗口 ["
237	                    + toGrade.getConsistencyMin() + ", " + toGrade.getConsistencyMax() + "] %");
238	        }
239	
240	        BigDecimal length = TransitionRules.transitionLengthM(speed, request.switchTimeSec());
241	
242	        order.setSwitchTimeSec(request.switchTimeSec());
243	        order.setMachineSpeedMMin(speed);
244	        order.setStockConsistencyPct(consistency);
245	        order.setTransitionLengthM(length);
246	        order.setStatus(TransitionStatus.EXECUTED);
247	        order.setExecutedAt(now());
248	        orderRepository.updateExecution(order);
249	
250	        // 停机清洗才占用清洗窗口；与执行结果在同一事务内登记，直切绝不产生清洗占用。
251	        if (Boolean.FALSE.equals(order.getDirectSwitch())) {
252	            String windowNo = "CW-" + orderNo;
253	            if (!cleaningWindowRepository.tryOccupy(windowNo, order.getPaperMachine(), orderNo, now())) {
254	                throw ApiException.conflict("停机清洗窗口冲突，纸机 " + order.getPaperMachine());
255	            }
256	        }
257	        if (cleaningWindowRepository.countActiveForOrder(orderNo) > 0
258	                && Boolean.TRUE.equals(order.getDirectSwitch())) {
259	            // 防御性不变式：直切单不得占用清洗窗口。
260	            throw ApiException.conflict("直切单不得占用清洗窗口");
261	        }
262	        return toView(order);
263	    }
264	
265	    /** 过渡料处置：过渡卷按卷号唯一登记，强制降级、入非正品库。 */
266	    @Transactional
267	    public OrderView dispose(String orderNo, DisposeRollsRequest request) {
268	        TransitionOrder order = requireOrder(orderNo);
269	        requireStatus(order, TransitionStatus.EXECUTED);
270	
271	        List<String> rollNos = request.rolls().stream().map(DisposeRollsRequest.RollItem::rollNo).toList();
272	        if (rollNos.stream().distinct().count() != rollNos.size()) {
273	            throw ApiException.conflict("同一次处置中卷号重复");
274	        }
275	        LocalDateTime registeredAt = now();
276	        try {
277	            for (DisposeRollsRequest.RollItem item : request.rolls()) {
278	                TransitionRoll roll = new TransitionRoll();
279	                roll.setRollNo(item.rollNo());
280	                roll.setOrderNo(orderNo);
281	                roll.setPaperMachine(order.getPaperMachine());
282	                roll.setLengthM(item.lengthM());
283	                rollRepository.insertDowngraded(roll, registeredAt);
284	                verdictEventRepository.insert(item.rollNo(), "FORCED_DOWNGRADE", null,
285	                        "DOWNGRADED", null, registeredAt);
286	            }
287	        } catch (DuplicateKeyException e) {
288	            throw ApiException.conflict("卷号已登记，过渡纸卷按卷号唯一");
289	        }
290	
291	        order.setStatus(TransitionStatus.DISPOSED);
292	        order.setDisposedAt(registeredAt);
293	        orderRepository.updateStatus(orderNo, TransitionStatus.DISPOSED, "disposed_at", registeredAt);
294	        return toView(order);
295	    }
296	
297	    /** 完成：释放纸机占用与清洗窗口，允许同机后续申请。 */
298	    @Transactional
299	    public OrderView complete(String orderNo) {
300	        TransitionOrder order = requireOrder(orderNo);
301	        requireStatus(order, TransitionStatus.DISPOSED);
302	        LocalDateTime completedAt = now();
303	        orderRepository.updateStatus(orderNo, TransitionStatus.COMPLETED, "completed_at", completedAt);
304	        machineSlotRepository.release(order.getPaperMachine(), orderNo);
305	        cleaningWindowRepository.release(orderNo, completedAt);
306	        order.setStatus(TransitionStatus.COMPLETED);
307	        order.setCompletedAt(completedAt);
308	        return toView(order);
309	    }
310	
311	    /** 归档（终态）：重复归档返回幂等成功；未完成不得归档。 */
312	    @Transactional
313	    public OrderView archive(String orderNo) {
314	        TransitionOrder order = requireOrder(orderNo);
315	        if (TransitionStatus.ARCHIVED.equals(order.getStatus())) {
316	            return toView(order);
317	        }
318	        requireStatus(order, TransitionStatus.COMPLETED);
319	        LocalDateTime archivedAt = now();
320	        orderRepository.updateStatus(orderNo, TransitionStatus.ARCHIVED, "archived_at", archivedAt);
321	        order.setStatus(TransitionStatus.ARCHIVED);
322	        order.setArchivedAt(archivedAt);
323	        return toView(order);
324	    }
325	
326	    public OrderView getOrder(String orderNo) {
327	        return toView(requireOrder(orderNo));
328	    }
329	
330	    /** 首次检验提交（requestId 幂等）；达门槛仅取得复议资格，过渡卷仍强制降级。 */
331	    @Transactional
332	    public IdempotentResult<RollView> submitInspection(InspectionRequest request) {
333	        String fingerprint = FingerprintUtil.sha256(request.requestId(), request);
334	        IdempotentRequest existing = lookupIdempotent(request.requestId(), BIZ_INSPECTION, fingerprint);
335	        if (existing != null) {
336	            return replay(existing, new TypeReference<RollView>() {
337	            });
338	        }
339	
340	        TransitionRoll roll = requireRoll(request.rollNo());
341	        TransitionOrder order = requireOrder(roll.getOrderNo());
342	
343	        // 归档终态后迟到：只记迟到事件，不改任何判定与入库状态；重放不重复登记事件。
344	        if (TransitionStatus.ARCHIVED.equals(order.getStatus())) {
345	            lateEventRepository.insert(order.getOrderNo(), roll.getRollNo(), "LATE_INSPECTION",
346	                    writeJson(request), now());
347	            RollView view = toRollView(roll);
348	            registerIdempotent(request.requestId(), BIZ_INSPECTION, fingerprint,
349	                    roll.getRollNo(), view);
350	            return new IdempotentResult<>(request.requestId(), false, view);
351	        }
352	
353	        boolean meets = meetsThreshold(request, order);
354	        try {
355	            RollInspection inspection = new RollInspection();
356	            inspection.setRollNo(roll.getRollNo());
357	            inspection.setInspectionType(INSPECTION_INITIAL);
358	            inspection.setRequestId(request.requestId());
359	            inspection.setAshValuePct(request.ashValuePct());
360	            inspection.setMoisturePct(request.moisturePct());
361	            inspection.setTensileIndex(request.tensileIndex());
362	            inspection.setBasisWeightGM2(request.basisWeightGM2());
363	            inspection.setMeetsThreshold(meets);
364	            // 过渡卷强制降级：达门槛只标记可复议，不自动改判。
365	            inspection.setVerdict(meets ? "GENUINE_ELIGIBLE" : "BELOW_THRESHOLD");
366	            inspectionRepository.insert(inspection, now());
367	        } catch (DuplicateKeyException e) {
368	            throw ApiException.conflict("该卷首次检验已提交");
369	        }
370	        rollRepository.updateInitialEligibility(roll.getRollNo(), meets);
371	
372	        TransitionRoll refreshed = rollRepository.getByRollNo(roll.getRollNo());
373	        registerIdempotent(request.requestId(), BIZ_INSPECTION, fingerprint,
374	                roll.getRollNo(), toRollView(refreshed));
375	        return new IdempotentResult<>(request.requestId(), false, toRollView(refreshed));
376	    }
377	
378	    /** 复议提交（requestId 幂等）：每卷至多受理一次，与首次判定并发形成唯一终态。 */
379	    @Transactional
380	    public IdempotentResult<RollView> submitReexam(ReexamRequest request) {
381	        String fingerprint = FingerprintUtil.sha256(request.requestId(), request);
382	        IdempotentRequest existing = lookupIdempotent(request.requestId(), BIZ_REEXAM, fingerprint);
383	        if (existing != null) {
384	            return replay(existing, new TypeReference<RollView>() {
385	            });
386	        }
387	
388	        TransitionRoll roll = requireRoll(request.rollNo());
389	        TransitionOrder order = requireOrder(roll.getOrderNo());
390	
391	        // 归档终态后迟到的复议：只记迟到事件，终态不变；重放不重复登记事件。
392	        if (TransitionStatus.ARCHIVED.equals(order.getStatus())) {
393	            lateEventRepository.insert(order.getOrderNo(), roll.getRollNo(), "LATE_REEXAM",
394	                    writeJson(request), now());
395	            RollView view = toRollView(roll);
396	            registerIdempotent(request.requestId(), BIZ_REEXAM, fingerprint,
397	                    roll.getRollNo(), view);
398	            return new IdempotentResult<>(request.requestId(), false, view);
399	        }
400	
401	        boolean initialEligible = inspectionRepository.find(roll.getRollNo(), INSPECTION_INITIAL)
402	                .map(RollInspection::isMeetsThreshold).orElse(false);
403	        if (!initialEligible) {
404	            throw ApiException.conflict("首次检验未达正品门槛或尚未检验，不具备复议资格");
405	        }
406	        if (roll.getReexamCount() > 0 || "UPGRADED".equals(roll.getVerdict())) {
407	            throw ApiException.conflict("该卷复议仅允许一次，终态已确定");
408	        }
409	
410	        boolean meets = meetsThreshold(request, order);
411	        LocalDateTime eventTime = now();
412	        try {
413	            RollInspection inspection = new RollInspection();
414	            inspection.setRollNo(roll.getRollNo());
415	            inspection.setInspectionType(INSPECTION_REEXAM);
416	            inspection.setRequestId(request.requestId());
417	            inspection.setAshValuePct(request.ashValuePct());
418	            inspection.setMoisturePct(request.moisturePct());
419	            inspection.setTensileIndex(request.tensileIndex());
420	            inspection.setBasisWeightGM2(request.basisWeightGM2());
421	            inspection.setMeetsThreshold(meets);
422	            inspection.setVerdict(meets ? "REEXAM_UPGRADED" : "REEXAM_REJECTED");
423	            // 唯一约束 (roll_no, inspection_type)：并发复议只有一个能插入，形成唯一终态。
424	            inspectionRepository.insert(inspection, eventTime);
425	        } catch (DuplicateKeyException e) {
426	            throw ApiException.conflict("该卷复议已受理，终态唯一");
427	        }
428	
429	        if (meets) {
430	            int updated = rollRepository.applyUpgrade(roll.getRollNo(), eventTime);
431	            if (updated == 0) {
432	                throw ApiException.conflict("该卷终态已确定，复议改判失败");
433	            }
434	            verdictEventRepository.insert(roll.getRollNo(), "REEXAM_UPGRADED",
435	                    "DOWNGRADED", "UPGRADED", request.requestId(), eventTime);
436	        } else {
437	            int updated = rollRepository.applyReexamReject(roll.getRollNo());
438	            if (updated == 0) {
439	                throw ApiException.conflict("该卷终态已确定，复议驳回失败");
440	            }
441	            verdictEventRepository.insert(roll.getRollNo(), "REEXAM_REJECTED",
442	                    "DOWNGRADED", "DOWNGRADED", request.requestId(), eventTime);
443	        }
444	
445	        TransitionRoll refreshed = rollRepository.getByRollNo(roll.getRollNo());
446	        registerIdempotent(request.requestId(), BIZ_REEXAM, fingerprint,
447	                roll.getRollNo(), toRollView(refreshed));
448	        return new IdempotentResult<>(request.requestId(), false, toRollView(refreshed));
449	    }
450	
451	    public RollView getRoll(String rollNo) {
452	        return toRollView(requireRoll(rollNo));
453	    }
454	
455	    /** 过渡料长度、降级卷明细与改判链复算。 */
456	    public TransitionRecomputeView recompute(String orderNo) {
457	        TransitionOrder order = requireOrder(orderNo);
458	        BigDecimal recomputed = null;
459	        if (order.getMachineSpeedMMin() != null && order.getSwitchTimeSec() != null) {
460	            recomputed = TransitionRules.transitionLengthM(
461	                    order.getMachineSpeedMMin(), order.getSwitchTimeSec());
462	        }
463	        List<RollView> rolls = rollRepository.findByOrderNo(orderNo).stream()
464	                .map(this::toRollView).toList();
465	        BigDecimal sumLength = rolls.stream()
466	                .map(RollView::lengthM)
467	                .filter(java.util.Objects::nonNull)
468	                .reduce(BigDecimal.ZERO, BigDecimal::add);
469	        return new TransitionRecomputeView(orderNo, order.getSwitchTimeSec(),
470	                order.getMachineSpeedMMin(), order.getTransitionLengthM(), recomputed,
471	                sumLength, rolls);
472	    }
473	
474	    /**
475	     * 执行中掺配比例调整（requestId 幂等）：生成新版本并切换当前版本，连续超差计数清零；
476	     * 同一订单同时刻只允许一次执行中调整（唯一索引 (order_no, source, created_at) 保证）。
477	     */
478	    @Transactional
479	    public IdempotentResult<BlendVersionView> adjustBlendRatio(String orderNo,
480	                                                               AdjustBlendRatioRequest request) {
481	        String fingerprint = FingerprintUtil.sha256(request.requestId(), request);
482	        IdempotentRequest existing = lookupIdempotent(request.requestId(), BIZ_ADJUST_BLEND, fingerprint);
483	        if (existing != null) {
484	            return replay(existing, new TypeReference<BlendVersionView>() {
485	            });
486	        }
487	
488	        TransitionOrder order = requireOrder(orderNo);
489	        if (TransitionStatus.PAUSED.equals(order.getStatus())) {
490	            throw ApiException.conflict("改品种单已失控暂停转人工，须复核确认恢复后再调整比例");
491	        }
492	        requireStatus(order, TransitionStatus.EXECUTED);
493	        if (!TransitionRules.withinBlendInterval(request.targetBlendRatioPct())) {
494	            throw ApiException.badRequest("掺配比例 " + request.targetBlendRatioPct()
495	                    + " 超出合成允许区间 [" + QualityThresholds.BLEND_RATIO_MIN_PCT
496	                    + ", " + QualityThresholds.BLEND_RATIO_MAX_PCT + "] %");
497	        }
498	
499	        BlendRatioVersion version = new BlendRatioVersion();
500	        version.setOrderNo(orderNo);
501	        version.setVersionNo(blendRatioVersionRepository.nextVersionNo(orderNo));
502	        version.setTargetRatioPct(request.targetBlendRatioPct());
503	        version.setSource(BLEND_SOURCE_ADJUST);
504	        version.setRequestId(request.requestId());
505	        version.setCreatedAt(now());
506	        if (!blendRatioVersionRepository.tryInsert(version)) {
507	            throw ApiException.conflict("同一订单同时刻只允许一次执行中调整: " + orderNo);
508	        }
509	        if (orderRepository.updateBlendAdjust(orderNo, version.getVersionNo()) == 0) {
510	            throw ApiException.conflict("改品种单执行状态已变更，比例调整失败: " + orderNo);
511	        }
512	
513	        BlendVersionView view = toVersionView(version);
514	        registerIdempotent(request.requestId(), BIZ_ADJUST_BLEND, fingerprint, orderNo, view);
515	        return new IdempotentResult<>(request.requestId(), false, view);
516	    }
517	
518	    /**
519	     * 实际掺配读数提交（requestId 幂等；按订单与采样时刻去重）：
520	     * 偏离目标超过 ±2%（恰 2% 合格）记超差，连续 3 个采样点超差判失控，
521	     * 失控即暂停执行并转人工，读数与暂停在同一事务内落库。
522	     */
523	    @Transactional
524	    public IdempotentResult<BlendReadingView> submitBlendReading(BlendReadingRequest request) {
525	        String fingerprint = FingerprintUtil.sha256(request.requestId(), request);
526	        IdempotentRequest existing = lookupIdempotent(request.requestId(), BIZ_BLEND_READING, fingerprint);
527	        if (existing != null) {
528	            return replay(existing, new TypeReference<BlendReadingView>() {
529	            });
530	        }
531	
532	        TransitionOrder order = requireOrder(request.orderNo());
533	        if (TransitionStatus.PAUSED.equals(order.getStatus())) {
534	            throw ApiException.conflict("改品种单已失控暂停转人工，复核确认恢复前不得登记读数");
535	        }
536	        requireStatus(order, TransitionStatus.EXECUTED);
537	        BlendRatioVersion current = blendRatioVersionRepository.findLatest(request.orderNo())
538	                .orElseThrow(() -> ApiException.conflict(
539	                        "改品种单未携带掺配比例维度，不得登记读数: " + request.orderNo()));
540	
541	        BigDecimal deviation = TransitionRules.blendDeviationPct(
542	                request.actualRatioPct(), current.getTargetRatioPct());
543	        boolean outOfTolerance = TransitionRules.isBlendOutOfTolerance(deviation);
544	
545	        BlendReading reading = new BlendReading();
546	        reading.setOrderNo(request.orderNo());
547	        reading.setVersionNo(current.getVersionNo());
548	        reading.setSampledAt(request.sampledAt());
549	        reading.setActualRatioPct(request.actualRatioPct());
550	        reading.setDeviationPct(deviation);
551	        reading.setOutOfTolerance(outOfTolerance);
552	        reading.setRequestId(request.requestId());
553	        reading.setCreatedAt(now());
554	        if (!blendReadingRepository.tryInsert(reading)) {
555	            throw ApiException.conflict("同一订单同一采样时刻已存在掺配读数: "
556	                    + request.orderNo() + " @ " + request.sampledAt());
557	        }
558	
559	        int streak = outOfTolerance ? order.getConsecutiveOutOfTolerance() + 1 : 0;
560	        order.setConsecutiveOutOfTolerance(streak);
561	        if (streak >= QualityThresholds.BLEND_OUT_OF_CONTROL_STREAK) {
562	            // 失控即暂停执行并转人工；与读数登记在同一事务内落库。
563	            order.setStatus(TransitionStatus.PAUSED);
564	            order.setPausedAt(now());
565	            blendControlEventRepository.insert(request.orderNo(), EVENT_OUT_OF_CONTROL_PAUSE,
566	                    request.requestId(), null,
567	                    "连续 " + streak + " 个采样点偏离目标超过 ±2%，暂停执行转人工", now());
568	        }
569	        if (orderRepository.updateBlendControl(order) == 0) {
570	            // 并发读数已先行暂停/变更状态：本次登记随事务回滚。
571	            throw ApiException.conflict("改品种单执行状态已变更，读数登记失败: " + request.orderNo());
572	        }
573	
574	        BlendReadingView view = toReadingView(reading);
575	        registerIdempotent(request.requestId(), BIZ_BLEND_READING, fingerprint,
576	                request.orderNo(), view);
577	        return new IdempotentResult<>(request.requestId(), false, view);
578	    }
579	
580	    /** 失控暂停后复核确认恢复（requestId 幂等）：恢复为执行中，连续超差计数清零。 */
581	    @Transactional
582	    public IdempotentResult<OrderView> resumeExecution(String orderNo, ResumeExecutionRequest request) {
583	        String fingerprint = FingerprintUtil.sha256(request.requestId(), request);
584	        IdempotentRequest existing = lookupIdempotent(request.requestId(), BIZ_RESUME, fingerprint);
585	        if (existing != null) {
586	            return replay(existing, new TypeReference<OrderView>() {
587	            });
588	        }
589	
590	        TransitionOrder order = requireOrder(orderNo);
591	        requireStatus(order, TransitionStatus.PAUSED);
592	        if (!Boolean.TRUE.equals(request.reviewConfirmed())) {
593	            throw ApiException.badRequest("恢复执行须复核确认（reviewConfirmed=true）");
594	        }
595	
596	        LocalDateTime resumedAt = now();
597	        if (orderRepository.updateResume(orderNo, resumedAt) == 0) {
598	            throw ApiException.conflict("改品种单状态已变更，恢复失败: " + orderNo);
599	        }
600	        blendControlEventRepository.insert(orderNo, EVENT_MANUAL_RESUME,
601	                request.requestId(), request.reviewedBy(), "复核确认恢复执行", resumedAt);
602	
603	        OrderView view = getOrder(orderNo);
604	        registerIdempotent(request.requestId(), BIZ_RESUME, fingerprint, orderNo, view);
605	        return new IdempotentResult<>(request.requestId(), false, view);
606	    }
607	
608	    /** 比例版本链查询：与改品种单号绑定留档。 */
609	    public List<BlendVersionView> listBlendVersions(String orderNo) {
610	        requireOrder(orderNo);
611	        return blendRatioVersionRepository.findByOrderNo(orderNo).stream()
612	                .map(this::toVersionView).toList();
613	    }
614	
615	    /** 掺配轨迹复算：版本链 + 按读数留存版本的目标复算偏离，历史订单（含已归档）均可复算。 */
616	    public BlendRecomputeView recomputeBlend(String orderNo) {
617	        TransitionOrder order = requireOrder(orderNo);
618	        List<BlendVersionView> versions = listBlendVersions(orderNo);
619	        java.util.Map<Integer, BigDecimal> targetByVersion = new java.util.HashMap<>();
620	        for (BlendVersionView v : versions) {
621	            targetByVersion.put(v.versionNo(), v.targetRatioPct());
622	        }
623	        List<BlendReadingView> readings = blendReadingRepository.findByOrderNo(orderNo).stream()
624	                .map(r -> {
625	                    BigDecimal target = targetByVersion.get(r.getVersionNo());
626	                    BigDecimal recomputedDeviation = TransitionRules.blendDeviationPct(
627	                            r.getActualRatioPct(), target);
628	                    return new BlendReadingView(r.getOrderNo(), r.getVersionNo(), r.getSampledAt(),
629	                            r.getActualRatioPct(), recomputedDeviation,
630	                            TransitionRules.isBlendOutOfTolerance(recomputedDeviation));
631	                })
632	                .toList();
633	        return new BlendRecomputeView(orderNo, order.getStatus(), order.getCurrentBlendVersion(),
634	                order.getConsecutiveOutOfTolerance(), versions, readings);
635	    }
636	
637	    // ------------------------------------------------------------------
638	    // 私有辅助方法（置于作用域末尾）
639	    // ------------------------------------------------------------------
640	
641	    private LocalDateTime now() {
642	        return LocalDateTime.now(clock);
643	    }
644	
645	    private TransitionOrder requireOrder(String orderNo) {
646	        return orderRepository.findByOrderNo(orderNo)
647	                .orElseThrow(() -> ApiException.notFound("改品种单不存在: " + orderNo));
648	    }
649	
650	    private TransitionRoll requireRoll(String rollNo) {
651	        return rollRepository.findByRollNo(rollNo)
652	                .orElseThrow(() -> ApiException.notFound("过渡纸卷不存在: " + rollNo));
653	    }
654	
655	    private void requireStatus(TransitionOrder order, String expected) {
656	        if (!expected.equals(order.getStatus())) {
657	            throw ApiException.conflict("改品种单状态为 " + order.getStatus()
658	                    + "，不允许该操作，期望状态 " + expected);
659	        }
660	    }
661	
662	    /**
663	     * 幂等记录查询：同键同参返回已完成的首次记录（调用方重放）；同键异参抛 409。
664	     * 读到未完成占位（首次事务尚未提交结果）时等待重试；查无记录则尝试插入占位，
665	     * 占位插入成功表示当前请求获得受理权，唯一索引冲突时重新查询。
666	     */
667	    private IdempotentRequest lookupIdempotent(String requestId, String bizType, String fingerprint) {
668	        for (int i = 0; i < 25; i++) {
669	            Optional<IdempotentRequest> found = idempotentRequestRepository.find(requestId);
670	            if (found.isPresent()) {
671	                IdempotentRequest record = found.get();
672	                if (!bizType.equals(record.getBizType()) || !fingerprint.equals(record.getFingerprint())) {
673	                    throw ApiException.conflict("requestId=" + requestId + " 已用于不同业务参数，冲突拒绝");
674	                }
675	                if (record.getResultJson() != null) {
676	                    return record;
677	                }
678	                // 首次事务仍在进行，等待其提交后重放。
679	                sleepBriefly();
680	                continue;
681	            }
682	            try {
683	                IdempotentRequest placeholder = new IdempotentRequest();
684	                placeholder.setRequestId(requestId);
685	                placeholder.setBizType(bizType);
686	                placeholder.setFingerprint(fingerprint);
687	                placeholder.setResultRef(null);
688	                placeholder.setResultJson(null);
689	                idempotentRequestRepository.insert(placeholder, now());
690	                return null;
691	            } catch (DuplicateKeyException e) {
692	                // 并发请求已插入占位（可能未提交），等待后重新查询。
693	                sleepBriefly();
694	            }
695	        }
696	        throw ApiException.conflict("并发幂等请求处理中，请稍后重放: " + requestId);
697	    }
698	
699	    private void sleepBriefly() {
700	        try {
701	            Thread.sleep(20);
702	        } catch (InterruptedException ie) {
703	            Thread.currentThread().interrupt();
704	            throw ApiException.conflict("并发幂等请求处理中断");
705	        }
706	    }
707	
708	    private void registerIdempotent(String requestId, String bizType, String fingerprint,
709	                                    String resultRef, Object resultView) {
710	        idempotentRequestRepository.updateResult(requestId, resultRef, writeJson(resultView));
711	    }
712	
713	    private <T> IdempotentResult<T> replay(IdempotentRequest record, TypeReference<T> type) {
714	        T data;
715	        try {
716	            byte[] bytes = record.getResultJson() == null
717	                    ? new byte[0] : record.getResultJson().getBytes(StandardCharsets.UTF_8);
718	            data = objectMapper.readValue(bytes, type);
719	        } catch (Exception e) {
720	            throw new IllegalStateException("幂等首次结果反序列化失败", e);
721	        }
722	        return new IdempotentResult<>(record.getRequestId(), true, data);
723	    }
724	
725	    private String writeJson(Object value) {
726	        try {
727	            return objectMapper.writeValueAsString(value);
728	        } catch (Exception e) {
729	            throw new IllegalStateException("JSON 序列化失败", e);
730	        }
731	    }
732	
733	    /**
734	     * 合成正品门槛判定（恰达边界视为合格）：
735	     * 灰分 ≤18%，水分 ∈ [4%,8%]，抗张指数 ≥45 Nm/g，定量与新品种标称克重偏差 ≤3%。
736	     */
737	    private boolean meetsThreshold(Object request, TransitionOrder order) {
738	        BigDecimal ash;
739	        BigDecimal moisture;
740	        BigDecimal tensile;
741	        BigDecimal basisWeight;
742	        if (request instanceof InspectionRequest ir) {
743	            ash = ir.ashValuePct();
744	            moisture = ir.moisturePct();
745	            tensile = ir.tensileIndex();
746	            basisWeight = ir.basisWeightGM2();
747	        } else {
748	            ReexamRequest rr = (ReexamRequest) request;
749	            ash = rr.ashValuePct();
750	            moisture = rr.moisturePct();
751	            tensile = rr.tensileIndex();
752	            basisWeight = rr.basisWeightGM2();
753	        }
754	        Grade toGrade = gradeRepository.findByCode(order.getToGrade())
755	                .orElseThrow(() -> ApiException.notFound("新品种不存在: " + order.getToGrade()));
756	        return TransitionRules.meetsQualityThreshold(ash, moisture, tensile,
757	                basisWeight, toGrade.getBasisWeight());
758	    }
759	
760	    private String newOrderNo() {
761	        byte[] bytes = new byte[2];
762	        RANDOM.nextBytes(bytes);
763	        return "TO-" + now().format(NO_FORMAT) + "-" + HexFormat.of().formatHex(bytes);
764	    }
765	
766	    private OrderView toView(TransitionOrder o) {
767	        return new OrderView(o.getOrderNo(), o.getPaperMachine(), o.getFromGrade(), o.getToGrade(),
768	                o.getBasisWeightFrom(), o.getBasisWeightTo(), o.getAshLevelFrom(), o.getAshLevelTo(),
769	                o.getBasisWeightDeltaPct(), o.getAshLevelDelta(), o.getDirectSwitch(), o.getWireFlush(),
770	                o.getSwitchTimeSec(), o.getMachineSpeedMMin(), o.getStockConsistencyPct(),
771	                o.getTransitionLengthM(), o.getCurrentBlendVersion(), o.getConsecutiveOutOfTolerance(),
772	                o.getStatus(), o.getAppliedAt(), o.getDecidedAt(),
773	                o.getExecutedAt(), o.getDisposedAt(), o.getCompletedAt(), o.getArchivedAt());
774	    }
775	
776	    private RollView toRollView(TransitionRoll r) {
777	        return new RollView(r.getRollNo(), r.getOrderNo(), r.getPaperMachine(), r.getLengthM(),
778	                r.getVerdict(), r.getWarehouseStatus(), r.isEligibleReexam(), r.getReexamCount(),
779	                r.getRegisteredAt(), r.getVerdictChangedAt(),
780	                verdictEventRepository.findByRollNo(r.getRollNo()));
781	    }
782	
783	    private BlendVersionView toVersionView(BlendRatioVersion v) {
784	        return new BlendVersionView(v.getOrderNo(), v.getVersionNo(), v.getTargetRatioPct(),
785	                v.getSource(), v.getRequestId(), v.getCreatedAt());
786	    }
787	
788	    private BlendReadingView toReadingView(BlendReading r) {
789	        return new BlendReadingView(r.getOrderNo(), r.getVersionNo(), r.getSampledAt(),
790	                r.getActualRatioPct(), r.getDeviationPct(), r.isOutOfTolerance());
791	    }
792	}
