45	        try {
46	            jdbc.update("""
47	                            INSERT INTO blend_ratio_version
48	                                (order_no, version_no, target_ratio_pct, source, request_id, created_at)
49	                            VALUES (?,?,?,?,?,?)
50	                            """,
51	                    version.getOrderNo(), version.getVersionNo(), version.getTargetRatioPct(),
52	                    version.getSource(), version.getRequestId(), Timestamp.valueOf(version.getCreatedAt()));
