        this.orderNo = orderNo;
    }

    public String getPaperMachine() {
        return paperMachine;
    }

    public void setPaperMachine(String paperMachine) {
        this.paperMachine = paperMachine;
    }

    public BigDecimal getLengthM() {
        return lengthM;
    }

