package com.example.starter.transition.repo;

import com.example.starter.transition.model.RecycleQuota;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

/**
 * 回收额度仓储：每卷至多一次登记（唯一索引保证）；
 * 扣量、调减与失效均为条件更新，并发下由行锁与版本号形成唯一次序。
 */
@Repository
public class RecycleQuotaRepository {

    private static final RowMapper<RecycleQuota> MAPPER = (rs, n) -> {
        RecycleQuota q = new RecycleQuota();
        q.setId(rs.getLong("id"));
        q.setRollNo(rs.getString("roll_no"));
        q.setRegisteredKg(rs.getBigDecimal("registered_kg"));
        q.setCurrentKg(rs.getBigDecimal("current_kg"));
        q.setConsumedKg(rs.getBigDecimal("consumed_kg"));
        q.setVersion(rs.getInt("version"));
        q.setStatus(rs.getString("status"));
        q.setInvalidatedReason(rs.getString("invalidated_reason"));
        q.setRequestId(rs.getString("request_id"));
        q.setCreatedAt(rs.getTimestamp("created_at").toLocalDateTime());
        q.setUpdatedAt(rs.getTimestamp("updated_at").toLocalDateTime());
        return q;
    };

    private final JdbcTemplate jdbc;

    public RecycleQuotaRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 登记回收额度：版本从 1 起，状态 ACTIVE。 */
    public void insert(RecycleQuota quota, LocalDateTime now) {
        jdbc.update("""
                        INSERT INTO recycle_quota
                            (roll_no, registered_kg, current_kg, consumed_kg, version,
                             status, invalidated_reason, request_id, created_at, updated_at)
                        VALUES (?, ?, ?, 0, 1, 'ACTIVE', NULL, ?, ?, ?)
                        """,
                quota.getRollNo(), quota.getRegisteredKg(), quota.getRegisteredKg(),
                quota.getRequestId(), Timestamp.valueOf(now), Timestamp.valueOf(now));
    }

    public Optional<RecycleQuota> findByRollNo(String rollNo) {
        List<RecycleQuota> list = jdbc.query(
                "SELECT * FROM recycle_quota WHERE roll_no = ?", MAPPER, rollNo);
        return list.stream().findFirst();
    }

    /**
     * 调减额度（乐观版本控制）：仅当版本匹配且额度仍有效时生效。
     *
     * @return 影响行数；0 表示版本过期或额度已失效
     */
    public int reduceWithVersion(String rollNo, int expectedVersion, java.math.BigDecimal newQuotaKg,
                                 LocalDateTime now) {
        return jdbc.update("""
                        UPDATE recycle_quota
                        SET current_kg = ?, version = version + 1, updated_at = ?
                        WHERE roll_no = ? AND version = ? AND status = 'ACTIVE'
                        """,
                newQuotaKg, Timestamp.valueOf(now), rollNo, expectedVersion);
    }

    /**
     * 投料扣量：仅当额度有效且未消费余额充足时生效，与版本自增同事务。
     *
     * @return 影响行数；0 表示额度不存在、已失效或余额不足
     */
    public int consume(String rollNo, java.math.BigDecimal kg, LocalDateTime now) {
        return jdbc.update("""
                        UPDATE recycle_quota
                        SET consumed_kg = consumed_kg + ?, version = version + 1, updated_at = ?
                        WHERE roll_no = ? AND status = 'ACTIVE' AND current_kg - consumed_kg >= ?
                        """,
                kg, Timestamp.valueOf(now), rollNo, kg);
    }

    /**
     * 复议改判正品时同步失效：未消费额度清零（当前额度降为累计消费），已消费凭据保留。
     *
     * @return 影响行数；0 表示无有效额度（未登记或已失效）
     */
    public int invalidateOnUpgrade(String rollNo, String reason, LocalDateTime now) {
        return jdbc.update("""
                        UPDATE recycle_quota
                        SET status = 'INVALIDATED', invalidated_reason = ?,
                            current_kg = consumed_kg, version = version + 1, updated_at = ?
                        WHERE roll_no = ? AND status = 'ACTIVE'
                        """,
                reason, Timestamp.valueOf(now), rollNo);
    }
}

package com.example.starter.transition.repo;

import com.example.starter.transition.model.FeedApplication;
import com.example.starter.transition.model.FeedConsumption;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

/**
 * 投料申请与消耗明细仓储：单头与明细同事务写入，已消费凭据永久保留。
 */
@Repository
public class FeedApplicationRepository {

    private static final RowMapper<FeedApplication> APP_MAPPER = (rs, n) -> {
        FeedApplication f = new FeedApplication();
        f.setId(rs.getLong("id"));
        f.setFeedNo(rs.getString("feed_no"));
        f.setOrderNo(rs.getString("order_no"));
        f.setBlendVersionNo(rs.getInt("blend_version_no"));
        f.setTotalPulpKg(rs.getBigDecimal("total_pulp_kg"));
        f.setRequiredRecycleKg(rs.getBigDecimal("required_recycle_kg"));
        f.setActualRecycleKg(rs.getBigDecimal("actual_recycle_kg"));
        f.setRequestId(rs.getString("request_id"));
        f.setCreatedAt(rs.getTimestamp("created_at").toLocalDateTime());
        return f;
    };

    private static final RowMapper<FeedConsumption> CONSUMPTION_MAPPER = (rs, n) -> {
        FeedConsumption c = new FeedConsumption();
        c.setId(rs.getLong("id"));
        c.setFeedNo(rs.getString("feed_no"));
        c.setRollNo(rs.getString("roll_no"));
        c.setKg(rs.getBigDecimal("kg"));
        c.setCreatedAt(rs.getTimestamp("created_at").toLocalDateTime());
        return c;
    };

    private final JdbcTemplate jdbc;

    public FeedApplicationRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insertApplication(FeedApplication feed) {
        jdbc.update("""
                        INSERT INTO feed_application
                            (feed_no, order_no, blend_version_no, total_pulp_kg,
                             required_recycle_kg, actual_recycle_kg, request_id, created_at)
                        VALUES (?,?,?,?,?,?,?,?)
                        """,
                feed.getFeedNo(), feed.getOrderNo(), feed.getBlendVersionNo(),
                feed.getTotalPulpKg(), feed.getRequiredRecycleKg(), feed.getActualRecycleKg(),
                feed.getRequestId(), Timestamp.valueOf(feed.getCreatedAt()));
    }

    public void insertConsumption(FeedConsumption consumption) {
        jdbc.update("""
                        INSERT INTO feed_consumption (feed_no, roll_no, kg, created_at)
                        VALUES (?,?,?,?)
                        """,
                consumption.getFeedNo(), consumption.getRollNo(), consumption.getKg(),
                Timestamp.valueOf(consumption.getCreatedAt()));
    }

    public Optional<FeedApplication> findApplication(String feedNo) {
        List<FeedApplication> list = jdbc.query(
                "SELECT * FROM feed_application WHERE feed_no = ?", APP_MAPPER, feedNo);
        return list.stream().findFirst();
    }

    public List<FeedConsumption> findConsumptionsByFeedNo(String feedNo) {
        return jdbc.query(
                "SELECT * FROM feed_consumption WHERE feed_no = ? ORDER BY id",
                CONSUMPTION_MAPPER, feedNo);
    }

    /** 按回收卷查询消耗凭据（含投料单号与订单号），供额度勾稽。 */
    public List<ConsumptionWithOrder> findConsumptionsByRollNo(String rollNo) {
        return jdbc.query("""
                        SELECT c.feed_no, f.order_no, c.kg, c.created_at
                        FROM feed_consumption c
                        JOIN feed_application f ON f.feed_no = c.feed_no
                        WHERE c.roll_no = ?
                        ORDER BY c.id
                        """,
                (rs, n) -> new ConsumptionWithOrder(
                        rs.getString("feed_no"), rs.getString("order_no"),
                        rs.getBigDecimal("kg"), rs.getTimestamp("created_at").toLocalDateTime()),
                rollNo);
    }

    /** 消耗凭据携订单号的投影。 */
    public record ConsumptionWithOrder(String feedNo, String orderNo,
                                       java.math.BigDecimal kg, LocalDateTime createdAt) {
    }
}

